#include <bits/stdc++.h>
#define MOD 1000000007LL

using namespace std;

struct VectorData {
  long long vals[30];
};

struct MatrixData {
  long long mat[30][30];
};

long long totalN, baseK;

int getVal(long long num) {
  if (num < baseK) return num;
  return (num + getVal(num / baseK)) % baseK;
}

MatrixData matricesArr[30], invMatricesArr[30];
MatrixData E[200][40], EI[200][40];
VectorData currentVec;

MatrixData multiplyMatrices(MatrixData a, MatrixData b) {
  MatrixData res;
  for (int i = 0; i < baseK; i++) {
    for (int j = 0; j < baseK; j++) {
      res.mat[i][j] = 0;
      for (int l = 0; l < baseK; l++) {
        res.mat[i][j] += (a.mat[i][l] * b.mat[l][j]) % MOD;
      }
      res.mat[i][j] %= MOD;
    }
  }
  return res;
}

VectorData multiplyMatrixVector(MatrixData m, VectorData v) {
  VectorData res;
  for (int i = 0; i < baseK; i++) {
    res.vals[i] = 0;
    for (int j = 0; j < baseK; j++) {
      res.vals[i] += (v.vals[j] * m.mat[i][j]) % MOD;
    }
    res.vals[i] %= MOD;
  }
  return res;
}

void precomputeAll() {
  for (int i = 0; i < baseK; i++) {
    E[0][i] = matricesArr[i];
    EI[0][i] = invMatricesArr[i];
  }
  int LOG = 0;
  long long t = totalN;
  while (t > 0) {
    LOG++;
    t /= baseK;
  }
  for (int j = 1; j <= LOG; j++) {
    E[j][0] = E[j - 1][0];
    EI[j][0] = EI[j - 1][0];
    for (int l = 1; l < baseK; l++) {
      E[j][0] = multiplyMatrices(E[j - 1][l], E[j][0]);
      EI[j][0] = multiplyMatrices(EI[j][0], EI[j - 1][l]);
    }
    for (int i = 1; i < baseK; i++) {
      E[j][i] = multiplyMatrices(E[j - 1][i - 1], multiplyMatrices(E[j][i - 1], EI[j - 1][i - 1]));
      EI[j][i] = multiplyMatrices(E[j - 1][i - 1], multiplyMatrices(EI[j][i - 1], EI[j - 1][i - 1]));
    }
  }
}

VectorData solveVector(long long n, VectorData v, int at) {
  if (n == 0) return v;
  int w = getVal(n / baseK);
  v = solveVector(n / baseK, v, at + 1);
  for (int i = 0; i < n % baseK; i++) {
    v = multiplyMatrixVector(E[at][(w + i) % baseK], v);
  }
  return v;
}

int main() {
  scanf("%lld %lld", &totalN, &baseK);
  for (int i = 0; i < baseK; i++) {
    currentVec.vals[i] = 1;
    for (int j = 0; j < baseK; j++) {
      for (int l = 0; l < baseK; l++) {
        if (j == l) {
          matricesArr[i].mat[j][l] = 1;
          invMatricesArr[i].mat[j][l] = 1;
        } else if (j == i) {
          matricesArr[i].mat[j][l] = 1;
          invMatricesArr[i].mat[j][l] = -1;
        } else {
          matricesArr[i].mat[j][l] = 0;
          invMatricesArr[i].mat[j][l] = 0;
        }
      }
    }
  }
  precomputeAll();
  currentVec = solveVector(totalN, currentVec, 0);
  long long totalSum = 0;
  for (int i = 0; i < baseK; i++) {
    totalSum += currentVec.vals[i];
  }
  totalSum--;
  totalSum %= MOD;
  if (totalSum < 0) totalSum += MOD;
  while (totalSum % (baseK - 1) != 0) {
    totalSum += MOD;
  }
  printf("%lld\n", totalSum / (baseK - 1));
}
